/**
 * Turn-labelling server: a tiny web UI for hand-labelling real turns.
 *
 * Why: the schema and the calibration can only be trusted against human labels on
 * real traffic. This serves the extracted turn digests, records one label per turn
 * and writes exactly the bench sample format — so labels feed `bench.ts` and a
 * calibration fit with no conversion step.
 *
 *   bun run labeler/server.ts [--port 8842] [--host 100.64.0.6]
 *
 * Data (never in git):
 *   $TURN_LABELER_DATA/candidates.jsonl   generated by extract.ts
 *   $TURN_LABELER_DATA/labels.jsonl       appended by this server
 *   $TURN_LABELER_DATA/skipped.jsonl      turns judged not labelable
 *
 * The server binds the tailnet address by default: it is a personal corpus view,
 * not something that should answer on a coffee-shop LAN.
 */

import { appendFileSync, existsSync, mkdirSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";

const DATA = process.env.TURN_LABELER_DATA ?? join(homedir(), ".local", "share", "pi-turn-classify-labeler");
const CANDIDATES = join(DATA, "candidates.jsonl");
const LABELS = join(DATA, "labels.jsonl");
const SKIPPED = join(DATA, "skipped.jsonl");

interface Candidate {
	id: string;
	state: Record<string, unknown>;
	meta: Record<string, unknown>;
}

interface LabelRecord {
	/** Bench-compatible sample: {id, state, expect}. */
	id: string;
	state: Record<string, unknown>;
	expect: Record<string, string>;
	meta: { labeledAt: string; ms?: number; note?: string; sessionFile?: unknown; turn?: unknown };
}

function readJsonl<T>(path: string): T[] {
	if (!existsSync(path)) return [];
	return readFileSync(path, "utf-8")
		.split("\n")
		.filter((line) => line.trim())
		.flatMap((line) => {
			try {
				return [JSON.parse(line) as T];
			} catch {
				return [];
			}
		});
}

function totalCandidates(): Candidate[] {
	return readJsonl<Candidate>(CANDIDATES);
}

function labeledIds(): Set<string> {
	return new Set(readJsonl<LabelRecord>(LABELS).map((record) => record.id));
}

function skippedIds(): Set<string> {
	return new Set(readJsonl<{ id: string }>(SKIPPED).map((record) => record.id));
}

/**
 * The labelling questions. `kind: "project"` is dynamic (from the digest),
 * `error` questions exist only on failed turns — the same conditional the
 * extension applies, so the corpus and the runtime agree on what was asked.
 */
interface QuestionDef {
	field: string;
	label: string;
	kind: "project" | "choice" | "boolean";
	options?: string[];
	errorOnly?: boolean;
}

const QUESTIONS: QuestionDef[] = [
	{ field: "project", label: "which project is this work about?", kind: "project" },
	{
		field: "activity",
		label: "what kind of work?",
		kind: "choice",
		options: ["implement", "debug", "test", "review", "research", "plan", "refactor", "ops", "docs", "setup", "chat"],
	},
	{ field: "work_done", label: "is the requested work complete?", kind: "boolean", options: ["yes", "no"] },
	{ field: "blocked", label: "is it blocked on something else?", kind: "boolean", options: ["yes", "no"] },
	{
		field: "attention",
		label: "does it need the user? what kind?",
		kind: "choice",
		options: ["none", "decision", "approval", "missing_info", "review"],
	},
	{
		field: "risk",
		label: "how consequential were the actions?",
		kind: "choice",
		options: ["none", "low", "medium", "high", "critical"],
	},
	{
		field: "artifact",
		label: "what did it produce?",
		kind: "choice",
		options: ["code", "test", "doc", "config", "issue", "data", "none"],
	},
	{
		field: "error_kind",
		label: "what kind of failure was the error?",
		kind: "choice",
		errorOnly: true,
		options: [
			"provider_overloaded",
			"rate_limited",
			"auth",
			"context_overflow",
			"network",
			"content_filter",
			"invalid_request",
			"bad_response",
			"tool_failed",
			"cancelled",
			"unclear",
		],
	},
	{
		field: "error_transient",
		label: "would a plain retry plausibly work?",
		kind: "boolean",
		errorOnly: true,
		options: ["yes", "no"],
	},
];

/** Answers allowed for a candidate (error questions only when it has an error). */
function answersFor(state: Record<string, unknown>): Record<string, string[]> {
	const hasError = Boolean(state.error) || Boolean(state.errored);
	const table: Record<string, string[]> = {};
	for (const question of QUESTIONS) {
		if (question.errorOnly && !hasError) continue;
		table[question.field] = question.options ?? [];
	}
	return table;
}

/** The questions to ask for a candidate, in order. */
function questionsFor(state: Record<string, unknown>): QuestionDef[] {
	const hasError = Boolean(state.error) || Boolean(state.errored);
	return QUESTIONS.filter((question) => !question.errorOnly || hasError);
}

function validateLabel(expect: Record<string, unknown>, allowed: Record<string, string[]>): string | undefined {
	for (const [field, options] of Object.entries(allowed)) {
		const value = expect[field];
		if (field === "project") {
			if (value !== undefined && (typeof value !== "string" || !value.trim())) return `"project" must be a string`;
			continue;
		}
		if (typeof value !== "string") return `missing answer for "${field}"`;
		if (!options.includes(value)) return `"${field}" must be one of ${options.join("|")}`;
	}
	return undefined;
}

const server = Bun.serve({
	port: Number(process.env.TURN_LABELER_PORT ?? 8842),
	hostname: process.env.TURN_LABELER_HOST ?? "0.0.0.0",
	async fetch(request) {
		const url = new URL(request.url);

		if (url.pathname === "/api/state") {
			const total = totalCandidates().length;
			const labeled = labeledIds().size;
			const skipped = skippedIds().size;
			return Response.json({
				total,
				labeled,
				skipped,
				remaining: Math.max(0, total - labeled - skipped),
				data: DATA,
				candidatesExported: existsSync(CANDIDATES),
			});
		}

		if (url.pathname === "/api/candidates") {
			const labeled = labeledIds();
			const skipped = skippedIds();
			const rows = totalCandidates().map((candidate) => ({
				id: candidate.id,
				done: labeled.has(candidate.id),
				skipped: skipped.has(candidate.id),
			}));
			return Response.json(rows);
		}

		if (url.pathname === "/api/next") {
			const after = url.searchParams.get("after");
			const rows = totalCandidates();
			const labeled = labeledIds();
			const skipped = skippedIds();
			const pending = rows.filter((row) => !labeled.has(row.id) && !skipped.has(row.id));
			if (pending.length === 0) return Response.json({ done: true });

			// `after` continues the queue; without it (first load) start at the first
			// turn that still needs a label, never at an already-labeled one.
			let candidate = pending[0] as Candidate;
			if (after) {
				const at = rows.findIndex((row) => row.id === after);
				if (at >= 0) {
					candidate = rows.slice(at + 1).find((row) => !labeled.has(row.id) && !skipped.has(row.id)) ?? candidate;
				}
			}
			return Response.json({
				done: false,
				candidate,
				position: rows.indexOf(candidate) + 1,
				total: rows.length,
				answers: answersFor(candidate.state),
				questions: questionsFor(candidate.state),
			});
		}

		if (url.pathname === "/api/label" && request.method === "POST") {
			const body = (await request.json()) as { id?: unknown; expect?: unknown; note?: unknown; ms?: unknown };
			if (typeof body.id !== "string" || !body.expect || typeof body.expect !== "object") {
				return Response.json({ error: "id and expect are required" }, { status: 400 });
			}
			const expect = body.expect as Record<string, unknown>;
			const candidate = totalCandidates().find((row) => row.id === body.id);
			if (!candidate) return Response.json({ error: `unknown candidate ${body.id}` }, { status: 404 });
			const problem = validateLabel(expect, answersFor(candidate.state));
			if (problem) return Response.json({ error: problem }, { status: 400 });
			if (labeledIds().has(body.id)) return Response.json({ error: "already labeled", id: body.id }, { status: 409 });

			const record: LabelRecord = {
				id: candidate.id,
				state: candidate.state,
				expect: expect as Record<string, string>,
				meta: {
					labeledAt: new Date().toISOString(),
					...(typeof body.ms === "number" ? { ms: body.ms } : {}),
					...(typeof body.note === "string" && body.note.trim() ? { note: body.note.trim() } : {}),
					sessionFile: candidate.meta.sessionFile,
					turn: candidate.meta.turn,
				},
			};
			mkdirSync(dirname(LABELS), { recursive: true });
			appendFileSync(LABELS, `${JSON.stringify(record)}\n`);
			return Response.json({ ok: true, labeled: labeledIds().size });
		}

		if (url.pathname === "/api/skip" && request.method === "POST") {
			const body = (await request.json()) as { id?: unknown };
			if (typeof body.id !== "string") return Response.json({ error: "id is required" }, { status: 400 });
			mkdirSync(dirname(SKIPPED), { recursive: true });
			appendFileSync(SKIPPED, `${JSON.stringify({ id: body.id, at: new Date().toISOString() })}\n`);
			return Response.json({ ok: true });
		}

		if (url.pathname === "/api/labels.jsonl") {
			if (!existsSync(LABELS)) return new Response("", { headers: { "content-type": "application/x-ndjson" } });
			return new Response(readFileSync(LABELS), {
				headers: { "content-type": "application/x-ndjson", "content-disposition": 'attachment; filename="labels.jsonl"' },
			});
		}

		if (url.pathname === "/" || url.pathname === "/index.html") {
			return new Response(readFileSync(join(import.meta.dir, "app.html")), {
				headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" },
			});
		}

		return new Response("not found", { status: 404 });
	},
});

console.log(`turn labeler on http://${server.hostname}:${server.port}`);
console.log(`data: ${DATA}`);
